     1	//! Formatting and conversion helpers that reproduce C++ semantics exactly.
     2	//!
     3	//! Two pieces of C++ behaviour matter for byte-identical output:
     4	//!
     5	//! * `std::ostream << std::fixed << std::setprecision(n) << double` — glibc
     6	//!   converts the *exact* binary value to decimal and rounds to nearest, ties
     7	//!   to even, which is also what Rust's `{:.n$}` does. Only the non-finite
     8	//!   spellings differ (`nan` / `-nan` / `inf` instead of `NaN` / `inf`), so
     9	//!   those are handled explicitly here.
    10	//! * `static_cast<int>(float)` — on x86-64 this compiles to `cvttss2si`, which
    11	//!   truncates toward zero and yields `INT_MIN` for NaN and for anything
    12	//!   outside the `int` range, rather than saturating the way Rust's `as` does.
    13	
    14	/// Formats `value` the way `std::ostream << std::fixed << std::setprecision(precision)` does.
    15	pub fn fixed(value: f64, precision: usize) -> String {
    16	    if value.is_nan() {
    17	        // glibc prints the NaN sign bit; x86 default QNaN (e.g. 0.0f / 0.0f) is negative.
    18	        return if value.is_sign_negative() {
    19	            String::from("-nan")
    20	        } else {
    21	            String::from("nan")
    22	        };
    23	    }
    24	    if value.is_infinite() {
    25	        return if value.is_sign_negative() {
    26	            String::from("-inf")
    27	        } else {
    28	            String::from("inf")
    29	        };
    30	    }
    31	    format!("{:.*}", precision, value)
    32	}
    33	
    34	/// Reproduces `static_cast<int>(v)` for a `float` on x86-64 (`cvttss2si`).
    35	pub fn f32_to_i32(v: f32) -> i32 {
    36	    // Anything not representable as an `int` after truncation gives the
    37	    // "integer indefinite" value, INT_MIN.
    38	    if v.is_nan() || v < -2_147_483_648.0_f32 || v >= 2_147_483_648.0_f32 {
    39	        i32::MIN
    40	    } else {
    41	        v as i32
    42	    }
    43	}
    44	
    45	#[cfg(test)]
    46	mod tests {
    47	    use super::*;
    48	
    49	    #[test]
    50	    fn fixed_matches_iostream_spelling() {
    51	        assert_eq!(fixed(75.0, 1), "75.0");
    52	        assert_eq!(fixed(0.0, 1), "0.0");
    53	        assert_eq!(fixed(-0.0, 1), "-0.0");
    54	        assert_eq!(fixed(100.0, 1), "100.0");
    55	        assert_eq!(fixed(12.5, 1), "12.5");
    56	        // ties round to even, exactly like glibc's %.1f
    57	        assert_eq!(fixed(0.25, 1), "0.2");
    58	        assert_eq!(fixed(0.75, 1), "0.8");
    59	        assert_eq!(fixed(f64::INFINITY, 1), "inf");
    60	        assert_eq!(fixed(f64::NEG_INFINITY, 1), "-inf");
    61	        assert_eq!(fixed(f64::NAN, 1), "nan");
    62	        assert_eq!(fixed(-f64::NAN, 1), "-nan");
    63	    }
    64	
    65	    #[test]
    66	    fn cvttss2si_semantics() {
    67	        assert_eq!(f32_to_i32(22.5), 22);
    68	        assert_eq!(f32_to_i32(-22.5), -22);
    69	        assert_eq!(f32_to_i32(0.0), 0);
    70	        assert_eq!(f32_to_i32(f32::NAN), i32::MIN);
    71	        assert_eq!(f32_to_i32(f32::INFINITY), i32::MIN);
    72	        assert_eq!(f32_to_i32(f32::NEG_INFINITY), i32::MIN);
    73	        assert_eq!(f32_to_i32(1e20), i32::MIN);
    74	        assert_eq!(f32_to_i32(-2_147_483_648.0), i32::MIN);
    75	    }
    76	}
